89	     * upper-cased first three letters of the last name and NNNN is a 4-digit,
90	     * zero-padded sequence one greater than the current number of owners.
91	     */
92	    public void assignCustomerCode(int existingOwnerCount) {
93	        String prefix = this.lastName.substring(0, Math.min(3, this.lastName.length())).toUpperCase(Locale.ROOT);
94	        this.customerCode = String.format("%s-%04d", prefix, existingOwnerCount + 1);
95	    }
96	
97	    public Integer getNamesakeCount() {
