110	        this.householdId = householdId;
111	    }
112	
113	    public String getEmail() {
114	        return this.email;
115	    }
116	
117	    public void setEmail(String email) {
118	        this.email = (email == null) ? null : email.toLowerCase(Locale.ROOT);
